// The GraphQL endpoint, served from prepared responses. Every response of the
// journey is fetched as text before the benchmark starts. A request is
// answered in a task of its own with a real Response, so that the loading
// state commits first and Apollo still reads and parses the body as it
// would a network response.
import { responseKey } from "../shared/search-input.mjs";
import { afterTask, track } from "./workload.js";

const responses = new Map();
const served = [];

export async function preloadResponses(baseUrl) {
    const manifest = await (await fetch(new URL("data/manifest.json", baseUrl))).json();
    await Promise.all(Object.entries(manifest).map(async ([key, file]) => {
        responses.set(key, await (await fetch(new URL(file, baseUrl))).text());
    }));
    return responses.size;
}

export function addResponse(key, text) {
    responses.set(key, text);
}

export function servedRequests() {
    return served;
}

const NOT_FOUND = JSON.stringify({ errors: [{ message: "PersistedQueryNotFound", extensions: { code: "PERSISTED_QUERY_NOT_FOUND" } }] });

export function workloadFetch(uri, init) {
    const body = JSON.parse(init.body);
    const key = responseKey(body.operationName, body.variables);
    const text = responses.get(key);
    served.push({ operationName: body.operationName, hash: body.extensions?.persistedQuery?.sha256Hash, bytes: text?.length ?? 0 });
    if (text === undefined)
        console.warn(`No prepared response for ${key}`);
    return track(new Promise((resolve) => {
        afterTask(() => resolve(new Response(text ?? NOT_FOUND, { status: 200, headers: { "content-type": "application/json" } })));
    }));
}
