// Where the code runs. On the server (the build's SSR pass) there is no
// window. In the browser, benchmark mode is on inside the Speedometer frame
// or with ?benchmark in the URL; then hydration waits for the first step
// and debounced calls wait for the step to flush them.
export const isServer = typeof window === "undefined";

export const benchmarkMode = !isServer && (window.top !== window || new URLSearchParams(location.search).has("benchmark"));

// The inline page configuration the server writes into #page-config.
let pageConfig = null;

export function getPageConfig() {
    if (!pageConfig && !isServer)
        pageConfig = JSON.parse(document.getElementById("page-config").textContent);
    return pageConfig;
}

export function setPageConfig(config) {
    pageConfig = config;
}
