import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import { catalogVersion, hasMessage, resolveTag, resolveText, subscribeCatalogs, translate } from "./catalog.js";
import { tracker } from "../telemetry/tracker.js";

const I18nContext = createContext({ locale: "en-gb", direction: "ltr" });

export function I18nProvider({ locale, children }) {
    const value = useMemo(() => ({ locale, direction: "ltr", intlLocale: locale.replace(/-(\w+)$/, (m, region) => `-${region.toUpperCase()}`) }), [locale]);
    return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useLocale() {
    return useContext(I18nContext);
}

function useCatalogVersion() {
    return useSyncExternalStore(subscribeCatalogs, catalogVersion, catalogVersion);
}

// Keys a component asked for that no catalog has, reported once per key.
const reportedMissing = new Set();

export function useTranslation() {
    const { intlLocale } = useContext(I18nContext);
    const version = useCatalogVersion();
    const missing = useRef(null);
    return useCallback((key, params) => {
        const text = translate(intlLocale, key, params);
        if (text === key && !reportedMissing.has(key)) {
            reportedMissing.add(key);
            missing.current = key;
        }
        return text;
    }, [intlLocale, version]);
}

// Resolves API text: LocalizedText objects, LocalizedString tags, or
// strings.
export function useLocalized() {
    const { locale } = useContext(I18nContext);
    const version = useCatalogVersion();
    const cache = useRef(null);
    return useCallback((value) => {
        if (!value)
            return "";
        if (typeof value === "string")
            return value;
        if (cache.current?.value === value && cache.current.version === version)
            return cache.current.text;
        const text = value.__typename === "LocalizedString" ? resolveTag(value) : resolveText(value);
        cache.current = { value, version, locale, text };
        return text;
    }, [version, locale]);
}

// Reports a message key that no catalog has, once per key, after the
// component that needed it has committed.
function useReportMissing(key) {
    useEffect(() => {
        if (!key || hasMessage(key) || reportedMissing.has(key))
            return;
        reportedMissing.add(key);
        tracker.push("sink", "i18n.missing", { key });
    }, [key]);
}

export function Translate({ id, params }) {
    const t = useTranslation();
    const text = useMemo(() => t(id, params), [t, id, params]);
    useReportMissing(id);
    return text;
}

export function LocalizedText({ value }) {
    const localized = useLocalized();
    const text = useMemo(() => localized(value), [localized, value]);
    useReportMissing(value?.tag?.key ?? (value?.__typename === "LocalizedString" ? value.key : null));
    return text;
}
