// The search state of the results page, kept in the URL. A navigation
// pushes the new URL and shows the pending state right away (the filter
// checks, the loading skeleton), then commits the new search in a
// transition, as a router with transitions does.
import { createContext, startTransition, useCallback, useContext, useMemo, useRef, useState } from "react";
import { normalizeFilters, searchParams } from "../shared/search-input.mjs";
import { isServer } from "./env.js";
import { tracker } from "./telemetry/tracker.js";

const SearchStateContext = createContext(null);

function normalize(state) {
    return { ...state, filters: normalizeFilters(state.filters) };
}

function pushUrl(state) {
    if (isServer)
        return;
    // Keep the parameters of the page that aren't ours, such as the
    // benchmark runner's.
    const params = new URLSearchParams(location.search);
    for (const key of ["dest_id", "dest_type", "checkin", "checkout", "group_adults", "group_children", "no_rooms", "nflt", "order", "offset"])
        params.delete(key);
    for (const [key, value] of searchParams(state))
        params.set(key, value);
    history.pushState({ search: state }, "", `${location.pathname}?${params}`);
}

export function SearchStateProvider({ initialState, children }) {
    const [state, setState] = useState(() => normalize(initialState));
    const [pendingState, setPendingState] = useState(null);
    const stateRef = useRef(state);
    stateRef.current = pendingState ?? state;

    const navigate = useCallback((update, reason) => {
        const next = normalize(typeof update === "function" ? update(stateRef.current) : { ...stateRef.current, ...update });
        stateRef.current = next;
        pushUrl(next);
        tracker.track("search.navigate", { reason, filters: next.filters.length, sort: next.sort, page: next.page });
        setPendingState(next);
        startTransition(() => {
            setState(next);
            setPendingState(null);
        });
    }, []);

    const value = useMemo(() => ({ state, pendingState, displayState: pendingState ?? state, isPending: pendingState !== null, navigate }), [state, pendingState, navigate]);
    return <SearchStateContext.Provider value={value}>{children}</SearchStateContext.Provider>;
}

export function useSearchState() {
    return useContext(SearchStateContext);
}

export function useToggleFilter() {
    const { navigate } = useSearchState();
    return useCallback((urlId, on) => navigate((state) => ({
        ...state,
        page: 0,
        filters: on ? [...state.filters, urlId] : state.filters.filter((f) => f !== urlId),
    }), "filter"), [navigate]);
}
